void test_out_of_bounds_read() {
    // Test for CWE-125: Out-of-bounds Read

    // Create a small document
    unsigned char doc_data[] = {0x41, 0x42, 0x43, 0x44, 0x45}; // "ABCDE"
    int doc_size = sizeof(doc_data);

    // Test reading beyond the document size
    printf("Testing out-of-bounds read beyond document size...\n");
    char result = get_doc_char_at(doc_data, doc_size, 0, doc_size); // Should be out of bounds

    // Test with text_offset that pushes char_index beyond bounds
    printf("Testing with text_offset that causes out-of-bounds access...\n");
    result = get_doc_char_at(doc_data, doc_size, 2, doc_size); // text_offset + char_index > doc_size

    // Test with negative offsets that might cause underflow
    printf("Testing with negative offsets...\n");
    result = get_doc_char_at(doc_data, doc_size, -1, 0);
    result = get_doc_char_at(doc_data, doc_size, 0, -1);

    // Test with very large char_index
    printf("Testing with very large char_index...\n");
    result = get_doc_char_at(doc_data, doc_size, 0, 1000);

    // Test with text_offset that exceeds document size
    printf("Testing with text_offset exceeding document size...\n");
    result = get_doc_char_at(doc_data, doc_size, doc_size + 1, 0);

    // Test combination of text_offset and char_index that exceeds bounds
    printf("Testing combined offset and index exceeding bounds...\n");
    result = get_doc_char_at(doc_data, doc_size, doc_size - 1, 2);

    printf("Security tests completed\n");
}

int main() {
    test_out_of_bounds_read();
    return 0;
}

